import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"Internals: crash dumps","description":"","frontmatter":{},"headers":[],"relativePath":"internals/crash-dump.md","filePath":"internals/crash-dump.md"}'),o={name:"internals/crash-dump.md"};function n(i,e,c,h,d,l){return a(),r("div",null,[...e[0]||(e[0]=[s(`<h1 id="internals-crash-dumps" tabindex="-1">Internals: crash dumps <a class="header-anchor" href="#internals-crash-dumps" aria-label="Permalink to &quot;Internals: crash dumps&quot;">​</a></h1><p><code>kernel/core/core_crash.c</code> + the exception path in <code>arch_exceptions.c</code>.</p><h2 id="the-panic-sequence" tabindex="-1">The panic sequence <a class="header-anchor" href="#the-panic-sequence" aria-label="Permalink to &quot;The panic sequence&quot;">​</a></h2><ol><li>The exception stub builds the frame (vector, RIP, registers, CR2/CR3 where relevant).</li><li>The dumper prints it to serial - the exact lines you need for a report.</li><li>A crashlog record goes to /etc - survives the reboot.</li><li>The machine halts (or the hardware watchdog resets it if one was armed - see <a href="./watchdog.html">watchdog.md</a>).</li></ol><h2 id="after-reboot" tabindex="-1">After reboot <a class="header-anchor" href="#after-reboot" aria-label="Permalink to &quot;After reboot&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; crashlog      (the record list)</span></span>
<span class="line"><span>oc&gt; dumpinfo      (the decoded dump: vector, fault address, registers)</span></span></code></pre></div><h2 id="why-ist-matters-here" tabindex="-1">Why IST matters here <a class="header-anchor" href="#why-ist-matters-here" aria-label="Permalink to &quot;Why IST matters here&quot;">​</a></h2><p>#DF (double fault) and #MC run on IST1 - their own stack - so a fault during a fault handler still reaches the dumper. The exception-exit path never context-switches on IST2 (BUG-0139): a context switch on an IST would corrupt the exception frame of the next nested fault.</p><h2 id="testing-it" tabindex="-1">Testing it <a class="header-anchor" href="#testing-it" aria-label="Permalink to &quot;Testing it&quot;">​</a></h2><p><code>crashtest</code> = deliberate panic, then <code>dumpinfo</code> proves the round trip. The regression battery checks <code>crashlog</code> on every run.</p>`,10)])])}const m=t(o,[["render",n]]);export{u as __pageData,m as default};
